def extract_section(text, heading):
    pattern = re.compile(
        r"^" + re.escape(heading) + r"\s*$([\s\S]*?)(?=^## |\Z)",
        re.MULTILINE,
    )
    match = pattern.search(text)
    if match is None:
        return ""
    return match.group(1)


def find_section_order_issues(text):
    issues = []

    title_matches = re.findall(
        r"^" + re.escape(REQUIRED_REPORT_TITLE) + r"\s*$",
        text,
        re.MULTILINE,
    )
    if len(title_matches) != 1:
        issues.append(REQUIRED_REPORT_TITLE)

    section_headings = re.findall(r"^##\s+[^\r\n]+$", text, re.MULTILINE)
    required_set = set(REQUIRED_SECTION_HEADINGS)

    for heading in REQUIRED_SECTION_HEADINGS:
        count = section_headings.count(heading)
        if count == 0:
            issues.append(heading)
        elif count > 1:
            issues.append(f"Duplicate required section: {heading}")

    for heading in section_headings:
        if heading not in required_set:
            issues.append(f"unknown report section: {heading}")

    if section_headings != REQUIRED_SECTION_HEADINGS:
        issues.append("Section order mismatch")

    return issues


def find_prohibited_content_issues(text):
    issues = []
    normalized_text = text.lower()

    for phrase in PROHIBITED_CONTENT_PHRASES:
        if phrase.lower() in normalized_text:
            issues.append(f"prohibited runtime report content: {phrase}")

    return issues


def find_not_found_fields(text):
    not_found_fields = []
    for field in RUNTIME_SUMMARY_FIELDS:
        pattern = re.compile(
            r"^-\s+" + re.escape(field) + r"\s*:\s*Not found\s*$",
            re.MULTILINE,
        )
        if pattern.search(text):
            not_found_fields.append(field)
    return not_found_fields


def find_not_found_fields_for_coverage(text):
    not_found_fields = []
    for field in REQUIRED_FIELDS:
        pattern = re.compile(
            r"^-\s+" + re.escape(field) + r"\s*:\s*Not found\s*$",
            re.MULTILINE,
        )
        if pattern.search(text):
            not_found_fields.append(field)
    return not_found_fields


def parse_bullet_value(section_text, field):
    match = re.search(
        r"^\s*-\s+" + re.escape(field) + r"\s*:\s*([^\r\n]+)\s*$",
        section_text,
        re.MULTILINE,
    )
    if match is None:
        return None
    return match.group(1).strip()


def parse_report_field_value(text, field):
    match = re.search(
        r"^-\s+" + re.escape(field) + r"\s*:\s*([^\r\n]+)\s*$",
        text,
        re.MULTILINE,
    )
    if match is None:
        return None
    return match.group(1).strip()


def parse_missing_fields_count(notes):
    match = re.search(r"Missing fields count:\s*([^\r\n]+)", notes)
    if match is None:
        return None, "Missing fields count"

    raw_count = match.group(1).strip()
    if not re.fullmatch(r"\d+", raw_count):
        return None, "Missing fields count is not an integer"

    return int(raw_count), ""


def find_listed_missing_fields(notes):
    listed_fields = []
    in_missing_fields = False

    for line in notes.splitlines():
        stripped = line.strip()
        if stripped == "- Missing fields:":
            in_missing_fields = True
            continue

        if not in_missing_fields:
            continue

        if not stripped:
            continue

        if not line.startswith("  - "):
            in_missing_fields = False
            continue

        field = line.strip()[2:].strip()
        if field:
            listed_fields.append(field)

    return listed_fields


