def parse_labeled_int(section_text, label):
    match = re.search(
        r"^\s*-\s+" + re.escape(label) + r":\s*([^\r\n]+)\s*$",
        section_text,
        re.MULTILINE,
    )
    if match is None:
        return None, f"{label}"

    raw_value = match.group(1).strip()
    if not re.fullmatch(r"\d+", raw_value):
        return None, f"{label} is not an integer"

    return int(raw_value), ""


def parse_missing_field_ratio(section_text):
    match = re.search(
        r"^\s*-\s+Missing field ratio:\s*([^\r\n]+)\s*$",
        section_text,
        re.MULTILINE,
    )
    if match is None:
        return None, "Missing field ratio"

    raw_ratio = match.group(1).strip()
    if not re.fullmatch(r"\d+(?:\.\d+)?%", raw_ratio):
        return None, "Missing field ratio is not a percentage"

    return float(raw_ratio[:-1]), ""


def parse_labeled_ratio(section_text, label):
    match = re.search(
        r"^\s*-\s+" + re.escape(label) + r":\s*([^\r\n]+)\s*$",
        section_text,
        re.MULTILINE,
    )
    if match is None:
        return None, f"{label}"

    raw_ratio = match.group(1).strip()
    if raw_ratio == "Not found":
        return raw_ratio, ""
    if not re.fullmatch(r"\d+(?:\.\d+)?%", raw_ratio):
        return None, f"{label} is not a percentage"

    return raw_ratio, ""


def parse_non_negative_int(value):
    if value is None or value == "Not found":
        return None
    if not re.fullmatch(r"\d+", value):
        return None
    return int(value)


def expected_log_ratio(numerator, denominator):
    if numerator is None or denominator is None:
        return "Not found"
    if denominator == 0:
        return "0.00%"
    return f"{(numerator / denominator * 100):.2f}%"


def parse_section_distribution(section_text, section_title):
    pattern = re.compile(
        r"^\s*-\s+"
        + re.escape(section_title)
        + r":\s*found\s+([^\s]+)\s*/\s*missing\s+([^\s]+)\s*$",
        re.MULTILINE,
    )
    match = pattern.search(section_text)
    if match is None:
        return None, None, f"Field coverage section missing: {section_title}"

    found_raw = match.group(1).strip()
    missing_raw = match.group(2).strip()
    if not re.fullmatch(r"\d+", found_raw) or not re.fullmatch(r"\d+", missing_raw):
        return None, None, f"Field coverage section values invalid: {section_title}"

    return int(found_raw), int(missing_raw), ""


def count_section_found_missing(text, fields):
    missing = 0
    for field in fields:
        pattern = re.compile(
            r"^-\s+" + re.escape(field) + r"\s*:\s*Not found\s*$",
            re.MULTILINE,
        )
        if pattern.search(text):
            missing += 1
    return len(fields) - missing, missing


def find_field_coverage_issues(text):
    issues = []
    coverage = extract_section(text, "## Field Coverage Summary")
    if not coverage:
        return ["Field Coverage Summary section"]

    total, total_issue = parse_labeled_int(coverage, "Total runtime fields")
    found, found_issue = parse_labeled_int(coverage, "Found runtime fields")
    missing, missing_issue = parse_labeled_int(coverage, "Missing runtime fields")
    ratio, ratio_issue = parse_missing_field_ratio(coverage)

    for issue in (total_issue, found_issue, missing_issue, ratio_issue):
        if issue:
            issues.append(issue)

    expected_total = sum(len(fields) for _, fields in SECTION_FIELDS)
    actual_missing = len(find_not_found_fields_for_coverage(text))
    actual_found = expected_total - actual_missing

    if total is not None:
        if total == 0:
            issues.append("Total runtime fields is zero")
        elif total != expected_total:
            issues.append(
                f"Total runtime fields mismatch: expected {expected_total}, found {total}"
            )

    if None not in (total, found, missing):
        if total != found + missing:
            issues.append("Field coverage total mismatch")

    if found is not None and found != actual_found:
        issues.append(
            f"Field coverage found mismatch: expected {actual_found}, found {found}"
        )

    if missing is not None and missing != actual_missing:
        issues.append(
            f"Field coverage missing mismatch: expected {actual_missing}, found {missing}"
        )

    if total is not None and total > 0 and ratio is not None:
        expected_ratio = round((actual_missing / total) * 100, 2)
        if abs(ratio - expected_ratio) > 0.005:
            issues.append(
                f"Missing field ratio mismatch: expected {expected_ratio:.2f}%, found {ratio:.2f}%"
            )

    section_found_total = 0
    section_missing_total = 0
    for section_title, fields in SECTION_FIELDS:
        section_found, section_missing, section_issue = parse_section_distribution(
            coverage, section_title
        )
        if section_issue:
            issues.append(section_issue)
            continue

        expected_found, expected_missing = count_section_found_missing(text, fields)
        section_found_total += section_found
        section_missing_total += section_missing

        if section_found != expected_found or section_missing != expected_missing:
            issues.append(f"Field coverage section mismatch: {section_title}")

    if found is not None and missing is not None:
        if section_found_total != found or section_missing_total != missing:
            issues.append("Field coverage section totals mismatch")

    return issues


def find_signal_observation_issues(text):
    issues = []
    section = extract_section(text, "## Signal Observation Summary")
    if not section:
        return ["Signal Observation Summary section"]

    for required in (
        "Signals are observation-only and are not trading instructions.",
        "Signal observation values are parsed from source text only.",
        "Not found signal fields are not inferred.",
        "This section does not enable real trading.",
    ):
        if required not in section:
            issues.append(required)

    actual_values = {}
    for field in SIGNAL_OBSERVATION_FIELDS:
        report_value = parse_report_field_value(text, field)
        summary_value = parse_bullet_value(section, field)
        if summary_value is None:
            issues.append(f"Signal Observation Summary missing field: {field}")
            continue
        if report_value is None:
            issues.append(f"Runtime summary missing signal field: {field}")
            continue
        actual_values[field] = report_value
        if summary_value != report_value:
            issues.append(f"Signal Observation Summary value mismatch: {field}")

    found_count, found_issue = parse_labeled_int(
        section, "Signal observation fields found"
    )
    missing_count, missing_issue = parse_labeled_int(
        section, "Signal observation fields missing"
    )
    if found_issue:
        issues.append(found_issue)
    if missing_issue:
        issues.append(missing_issue)

    actual_missing_fields = [
        field
        for field in SIGNAL_OBSERVATION_FIELDS
        if actual_values.get(field) == "Not found"
    ]
    actual_found_count = len(SIGNAL_OBSERVATION_FIELDS) - len(actual_missing_fields)

    if found_count is not None and found_count != actual_found_count:
        issues.append(
            f"Signal observation found mismatch: expected {actual_found_count}, found {found_count}"
        )
    if missing_count is not None and missing_count != len(actual_missing_fields):
        issues.append(
            "Signal observation missing mismatch: "
            f"expected {len(actual_missing_fields)}, found {missing_count}"
        )

    missing_mode, listed_fields = find_listed_signal_observation_missing_fields(section)
    if not actual_missing_fields:
        if missing_mode != "none":
            issues.append("Signal observation missing fields should be none")
        if listed_fields:
            issues.append("Signal observation unexpected missing field list")
    else:
        if missing_mode == "none" or not listed_fields:
            issues.append("Signal observation missing field list")

        actual_field_set = set(actual_missing_fields)
        listed_field_set = set(listed_fields)

        for field in listed_fields:
            if field not in SIGNAL_OBSERVATION_FIELDS:
                issues.append(f"Unknown Signal Observation missing field: {field}")

        for field in actual_missing_fields:
            if field not in listed_field_set:
                issues.append(f"Signal Observation missing field: {field}")

        for field in listed_fields:
            if field in SIGNAL_OBSERVATION_FIELDS and field not in actual_field_set:
                issues.append(f"Signal Observation unexpected missing field: {field}")

    return issues


