def find_log_throttle_issues(text):
    issues = []
    section = extract_section(text, "## Log Throttle Summary")
    if not section:
        return ["Log Throttle Summary section"]

    for required in (
        "Log throttle values are parsed from source text only.",
        "Not found log throttle fields are not inferred.",
        "Log throttle summary does not enable real trading.",
        "Log throttle ratios are reporting metrics, not trading signals.",
    ):
        if required not in section:
            issues.append(required)

    actual_values = {}
    for field in LOG_THROTTLE_FIELDS:
        report_value = parse_report_field_value(text, field)
        summary_value = parse_bullet_value(section, field)
        if summary_value is None:
            issues.append(f"Log Throttle Summary missing field: {field}")
            continue
        if report_value is None:
            issues.append(f"Runtime summary missing log throttle field: {field}")
            continue
        actual_values[field] = report_value
        if summary_value != report_value:
            issues.append(f"Log Throttle Summary value mismatch: {field}")

    found_count, found_issue = parse_labeled_int(
        section, "Log throttle fields found"
    )
    missing_count, missing_issue = parse_labeled_int(
        section, "Log throttle fields missing"
    )
    if found_issue:
        issues.append(found_issue)
    if missing_issue:
        issues.append(missing_issue)

    actual_missing_fields = [
        field
        for field in LOG_THROTTLE_FIELDS
        if actual_values.get(field) == "Not found"
    ]
    actual_found_count = len(LOG_THROTTLE_FIELDS) - len(actual_missing_fields)

    if found_count is not None and found_count != actual_found_count:
        issues.append(
            f"Log throttle found mismatch: expected {actual_found_count}, found {found_count}"
        )
    if missing_count is not None and missing_count != len(actual_missing_fields):
        issues.append(
            "Log throttle missing mismatch: "
            f"expected {len(actual_missing_fields)}, found {missing_count}"
        )

    printed_risk = parse_non_negative_int(actual_values.get("printedRiskRejectLogs"))
    suppressed_risk = parse_non_negative_int(
        actual_values.get("suppressedRiskRejectLogs")
    )
    risk_denominator = None
    if printed_risk is not None and suppressed_risk is not None:
        risk_denominator = printed_risk + suppressed_risk

    ratio_checks = [
        (
            "Risk reject log print ratio",
            expected_log_ratio(printed_risk, risk_denominator),
        ),
        (
            "New bar log print ratio",
            expected_log_ratio(
                parse_non_negative_int(actual_values.get("printedNewBarLogs")),
                parse_non_negative_int(actual_values.get("totalNewBarLogEvents")),
            ),
        ),
        (
            "Signal log print ratio",
            expected_log_ratio(
                parse_non_negative_int(actual_values.get("printedSignalLogs")),
                parse_non_negative_int(actual_values.get("totalSignalLogEvents")),
            ),
        ),
    ]

    for label, expected in ratio_checks:
        ratio, ratio_issue = parse_labeled_ratio(section, label)
        if ratio_issue:
            issues.append(ratio_issue)
            continue
        if ratio != expected:
            issues.append(
                f"{label} mismatch: expected {expected}, found {ratio}"
            )

    missing_mode, listed_fields = find_listed_log_throttle_missing_fields(section)
    if not actual_missing_fields:
        if missing_mode != "none":
            issues.append("Log throttle missing fields should be none")
        if listed_fields:
            issues.append("Log throttle unexpected missing field list")
    else:
        if missing_mode == "none" or not listed_fields:
            issues.append("Log throttle missing field list")

        actual_field_set = set(actual_missing_fields)
        listed_field_set = set(listed_fields)

        for field in listed_fields:
            if field not in LOG_THROTTLE_FIELDS:
                issues.append(f"Unknown Log Throttle missing field: {field}")

        for field in actual_missing_fields:
            if field not in listed_field_set:
                issues.append(f"Log Throttle missing field: {field}")

        for field in listed_fields:
            if field in LOG_THROTTLE_FIELDS and field not in actual_field_set:
                issues.append(f"Log Throttle unexpected missing field: {field}")

    return issues


def find_missing_field_notes_issues(text):
    issues = []
    notes = extract_section(text, "## Missing Field Notes")
    if not notes:
        return ["Missing Field Notes section"]

    not_found_fields = find_not_found_fields(text)
    listed_fields = find_listed_missing_fields(notes)
    reported_count, count_issue = parse_missing_fields_count(notes)
    actual_count = len(not_found_fields)

    if count_issue:
        issues.append(count_issue)
    elif reported_count != actual_count:
        issues.append(
            f"Missing fields count mismatch: expected {actual_count}, found {reported_count}"
        )

    if not_found_fields and not listed_fields:
        issues.append("Missing Field Notes listed field name")

    actual_field_set = set(not_found_fields)
    listed_field_set = set(listed_fields)

    for field in listed_fields:
        if field not in RUNTIME_SUMMARY_FIELDS:
            issues.append(f"Unknown Missing Field Notes field: {field}")

    for field in not_found_fields:
        if field not in listed_field_set:
            issues.append(f"Missing Field Notes missing field: {field}")

    for field in listed_fields:
        if field in RUNTIME_SUMMARY_FIELDS and field not in actual_field_set:
            issues.append(f"Missing Field Notes unexpected field: {field}")

    return issues


