def parse_args():
    parser = argparse.ArgumentParser(
        description="Validate a generated backtest runtime summary draft report."
    )
    parser.add_argument("--report", required=True, help="Generated Markdown report path.")
    return parser.parse_args()


def read_report(report_path):
    try:
        return report_path.read_text(encoding="utf-8")
    except UnicodeDecodeError:
        return report_path.read_text(encoding="utf-8-sig")


def find_missing_items(text):
    missing = []

    missing.extend(find_section_order_issues(text))
    missing.extend(find_prohibited_content_issues(text))

    for required in REQUIRED_SUBSTRINGS:
        if required not in text:
            missing.append(required)

    for field in REQUIRED_FIELDS:
        if field not in text:
            missing.append(field)

    missing.extend(find_missing_field_notes_issues(text))
    missing.extend(find_field_coverage_issues(text))
    missing.extend(find_signal_observation_issues(text))
    missing.extend(find_risk_rejection_issues(text))
    missing.extend(find_log_throttle_issues(text))

    return missing


def main():
    args = parse_args()
    report_path = Path(args.report)

    if not report_path.exists():
        print("Validation failed")
        print(f"Missing report file: {report_path}")
        return 1

    text = read_report(report_path)
    missing = find_missing_items(text)

    if missing:
        print("Validation failed")
        print(f"Report: {report_path}")
        print("Missing items:")
        for item in missing:
            print(f"- {item}")
        return 1

    print("Backtest runtime report validation passed")
    print("Validation passed")
    print(f"Report: {report_path}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
